jumpDialog.addEventListener('close',()=>search.value='');jumpDialog.addEventListener('click',e=>{if(e.target===jumpDialog){const r=jumpDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)jumpDialog.close()}});

// A public signature wall. Stroke data is bounded and rendered as safe SVG paths.
const GUEST_API=['127.0.0.1','localhost'].includes(location.hostname)?'http://127.0.0.1:8787/entries':'https://rusetiq-guestbook.aarush-uae.workers.dev/entries';
const signDialog=$('#sign-dialog'),signCanvas=$('#signature-pad'),pen=signCanvas.getContext('2d');let strokes=[],activeStroke=null,ink='#e0dfd5',typedMode=false,wallEntries=[],wallTotal=0,wallNext=null,wallLoading=false,owned={};
try{const data=JSON.parse(localStorage.getItem('rusetiq-owned-signatures')||'{}');if(data&&typeof data==='object')owned=data}catch{}
function signaturePath(stroke){if(!stroke.length)return '';const p=stroke.map(([x,y])=>[x*540,y*180]);if(p.length===1)return `M ${p[0][0]} ${p[0][1]} l .1 .1`;let d=`M ${p[0][0].toFixed(2)} ${p[0][1].toFixed(2)}`;for(let i=1;i<p.length-1;i++){d+=` Q ${p[i][0].toFixed(2)} ${p[i][1].toFixed(2)} ${((p[i][0]+p[i+1][0])/2).toFixed(2)} ${((p[i][1]+p[i+1][1])/2).toFixed(2)}`}d+=` L ${p.at(-1)[0].toFixed(2)} ${p.at(-1)[1].toFixed(2)}`;return d}
function drawSignature(){pen.clearRect(0,0,1080,360);pen.save();pen.scale(2,2);pen.strokeStyle=ink;pen.lineWidth=2.1;pen.lineCap='round';pen.lineJoin='round';strokes.forEach(s=>{if(s.length===1){pen.beginPath();pen.fillStyle=ink;pen.arc(s[0][0]*540,s[0][1]*180,1,0,Math.PI*2);pen.fill()}else pen.stroke(new Path2D(signaturePath(s)))});pen.restore();updateSigningState()}
function updateSigningState(){const points=strokes.reduce((n,s)=>n+s.length,0);$('#signature-placeholder').classList.toggle('hidden',points>0);$('#signature-clear').disabled=typedMode?!$('#typed-signature').value:!points;$('#signature-undo').disabled=typedMode||!strokes.length;$('#signature-submit').disabled=!$('#sign-name').value.trim()||(typedMode?!$('#typed-signature').value.trim():points<3)}
function pointFromEvent(e){const r=signCanvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),e.pointerType==='pen'?Math.max(.1,e.pressure):.5]}
signCanvas.addEventListener('pointerdown',e=>{if(e.button!==0||strokes.length>=80)return;e.preventDefault();signCanvas.setPointerCapture(e.pointerId);activeStroke=[pointFromEvent(e)];strokes.push(activeStroke);drawSignature()});
signCanvas.addEventListener('pointermove',e=>{if(!activeStroke)return;e.preventDefault();const events=e.getCoalescedEvents?.()||[e];for(const ev of events){if(strokes.reduce((n,s)=>n+s.length,0)>=2200)break;const p=pointFromEvent(ev),last=activeStroke.at(-1);if(Math.hypot((p[0]-last[0])*540,(p[1]-last[1])*180)>1.2)activeStroke.push(p)}drawSignature()});
function finishStroke(e){if(!activeStroke)return;activeStroke=null;if(signCanvas.hasPointerCapture(e.pointerId))signCanvas.releasePointerCapture(e.pointerId);drawSignature()}
signCanvas.addEventListener('pointerup',finishStroke);signCanvas.addEventListener('pointercancel',finishStroke);signCanvas.addEventListener('lostpointercapture',()=>activeStroke=null);
$('#signature-undo').onclick=()=>{strokes.pop();drawSignature()};$('#signature-clear').onclick=()=>{strokes=[];$('#typed-signature').value='';drawSignature()};
document.querySelectorAll('[data-ink]').forEach(b=>b.onclick=()=>{ink=b.dataset.ink;document.querySelectorAll('[data-ink]').forEach(a=>{const on=a===b;a.classList.toggle('selected',on);a.setAttribute('aria-pressed',String(on))});$('#typed-signature').style.color=ink;drawSignature()});
$('#signature-type').onclick=()=>{typedMode=!typedMode;$('.signature-paper').hidden=typedMode;$('#typed-signature-wrap').hidden=!typedMode;$('#signature-type').textContent=typedMode?'rather draw it?':'rather type it?';if(typedMode)$('#typed-signature').focus();updateSigningState()};
$('#sign-name').addEventListener('input',updateSigningState);$('#typed-signature').addEventListener('input',updateSigningState);$('#sign-message').addEventListener('input',()=>$('#message-count').textContent=$('#sign-message').value.length+' / 120');
function openSigningPad(){signDialog.showModal();$('#sign-error').textContent='';drawSignature();$('#sign-name').focus()}$('#sign-open').onclick=openSigningPad;$('#sign-shortcut').onclick=openSigningPad;
signDialog.addEventListener('click',e=>{if(e.target===signDialog){const r=signDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)signDialog.close()}});
function createSignatureArt(entry){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 540 180');svg.setAttribute('class','signature-art');svg.setAttribute('role','img');svg.setAttribute('aria-label',`signature of ${entry.name}`);if(entry.drawing.typed){const text=document.createElementNS(ns,'text');text.setAttribute('x','270');text.setAttribute('y','90');text.setAttribute('fill',entry.ink);text.setAttribute('class','typed-art');text.textContent=entry.drawing.typed;svg.append(text)}else{for(const stroke of entry.drawing.strokes){const path=document.createElementNS(ns,'path');path.setAttribute('d',signaturePath(stroke));path.setAttribute('fill','none');path.setAttribute('stroke',entry.ink);svg.append(path)}}return svg}
function renderWall(newId){const wall=$('#signature-wall');wall.replaceChildren();$('#guest-count').textContent=wallTotal+' '+(wallTotal===1?'signature':'signatures');if(!wallEntries.length){const p=document.createElement('p');p.className='empty-wall';p.textContent='the first scribble could be yours.';wall.append(p)}wallEntries.forEach(entry=>{const card=document.createElement('article');card.className='signature-card'+(entry.id===newId?' is-new':'');card.append(createSignatureArt(entry));const note=document.createElement('p');note.textContent=entry.message||'left a little mark.';const meta=document.createElement('div');meta.className='signature-card-meta';const name=document.createElement('strong');name.textContent=entry.name;const time=document.createElement('time');time.dateTime=new Date(entry.created_at).toISOString();time.textContent=new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(entry.created_at);meta.append(name,time);card.append(note,meta);if(owned[entry.id]){const remove=document.createElement('button');remove.className='signature-remove';remove.textContent='remove';remove.setAttribute('aria-label','remove my signature');remove.onclick=async()=>{remove.disabled=true;try{await guestRequest('DELETE',{id:entry.id,deleteToken:owned[entry.id]});delete owned[entry.id];saveOwnership();wallEntries=wallEntries.filter(e=>e.id!==entry.id);wallTotal=Math.max(0,wallTotal-1);if(wallNext!==null)wallNext=Math.max(wallEntries.length,wallNext-1);renderWall();toast('your mark has been removed.')}catch(e){remove.disabled=false;toast(e.message)}};card.append(remove)}card.addEventListener('pointerenter',()=>animateInk(card));wall.append(card)});$('#guest-more').hidden=wallNext===null;updateProgress()}
function animateInk(card){if(reducedMotion.matches)return;card.querySelectorAll('path').forEach((path,i)=>{const length=path.getTotalLength();path.getAnimations().forEach(a=>a.cancel());path.animate([{strokeDasharray:length,strokeDashoffset:length},{strokeDasharray:length,strokeDashoffset:0}],{duration:700,delay:Math.min(i*40,350),easing:'ease-out',fill:'backwards'})})}
function saveOwnership(){try{localStorage.setItem('rusetiq-owned-signatures',JSON.stringify(owned))}catch{}}
async function guestRequest(method,data,query=''){let r;try{r=await fetch(GUEST_API+query,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined})}catch{throw new Error('couldn’t reach the guestbook. try again in a moment.')}let json;try{json=await r.json()}catch{throw new Error('the guestbook is resting. try again shortly.')}if(!r.ok)throw new Error(json.error||'couldn’t reach the guestbook.');return json}
async function loadWall(reset=true){if(wallLoading)return;wallLoading=true;$('#guest-more').disabled=true;try{const data=await guestRequest('GET',null,`?limit=${reset?6:12}&offset=${reset?0:wallNext||0}`);wallEntries=reset?data.entries:[...wallEntries,...data.entries];wallTotal=data.total;wallNext=data.next;renderWall()}catch(e){if(reset){const p=document.createElement('p');p.className='guest-error';p.textContent=e.message;const retry=document.createElement('button');retry.textContent='retry';retry.onclick=()=>loadWall();p.append(retry);$('#signature-wall').replaceChildren(p);$('#guest-count').textContent='come back in a moment';}else toast(e.message)}finally{wallLoading=false;$('#guest-more').disabled=false}}
$('#guest-more').onclick=()=>loadWall(false);
$('#sign-form').onsubmit=async e=>{e.preventDefault();const submit=$('#signature-submit');if(submit.disabled)return;submit.disabled=true;submit.textContent='leaving your mark...';$('#sign-error').textContent='';try{const result=await guestRequest('POST',{name:$('#sign-name').value,message:$('#sign-message').value,website:$('#sign-website').value,ink,drawing:typedMode?{typed:$('#typed-signature').value}:{strokes}});owned[result.entry.id]=result.deleteToken;saveOwnership();wallEntries.unshift(result.entry);wallTotal++;if(wallNext!==null)wallNext++;renderWall(result.entry.id);strokes=[];$('#sign-form').reset();$('#message-count').textContent='0 / 120';signDialog.close();drawSignature();toast('you were here. ✦');if(!reducedMotion.matches){const card=$('.signature-card');card.querySelectorAll('path').forEach((p,i)=>{const length=p.getTotalLength();p.animate([{strokeDasharray:length,strokeDashoffset:length},{strokeDasharray:length,strokeDashoffset:0}],{duration:800,delay:i*90,easing:'ease-out',fill:'backwards'})})}}catch(error){$('#sign-error').textContent=error.message}finally{submit.innerHTML='sign the guestbook <span>↗</span>';updateSigningState()}};
loadWall();
